/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Iap_Status iap_sector_erase (const UInt8 sector_start , const UInt8 sector_end)
{
  UInt32 results [2]          ;
  UInt32 command [5] = { 52 } ;

  command [1] = sector_start        ;
  command [2] = sector_end          ;
  command [3] = CPU_CLOCK_HZ / 1000 ; // In KHz

  iap_execute (command,results)     ;

  return (Iap_Status) results [0]   ;
}

